"""Real touch swipe, outside tap, focus trapping and motion preferences for the drawer."""
import os,json
from pathlib import Path
from playwright.sync_api import sync_playwright
from browser_auth import register_local
ROOT=Path(__file__).resolve().parents[1];BASE=os.getenv('LAB_TEST_BASE','http://127.0.0.1:8044/')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-webgl']);ctx=b.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True,reduced_motion='no-preference');q=ctx.new_page();errors=[];q.on('pageerror',lambda e:errors.append(str(e)));register_local(q,BASE,'Touch Learner');q.add_locator_handler(q.locator('#earnedDialog[open]'),lambda d:d.locator('button').click());before=q.evaluate('JSON.stringify(state)')
 drawer=q.locator('#profileMenu');q.locator('#navigationToggle').click();assert drawer.evaluate('(e)=>getComputedStyle(e).animationName')=='sidebar-slide-in';q.wait_for_timeout(300);assert q.locator('[data-profile-compact]').is_hidden();assert q.locator('[data-profile-close]').is_visible()
 # Swiping over a navigation link must not trigger that link's click.
 row=q.locator('.sidebar-link[href="#home"]');box=row.bounding_box();x=box['x']+box['width']-30;y=box['y']+box['height']/2;url=q.url;cdp=ctx.new_cdp_session(q);cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':x,'y':y}]})
 for dx in [20,60,110,170]:cdp.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':x-dx,'y':y+1}]})
 cdp.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});q.wait_for_function('!document.getElementById("profileMenu").open');assert q.url==url;assert q.locator('#navigationToggle').get_attribute('aria-expanded')=='false'
 q.wait_for_timeout(300);q.locator('#navigationToggle').click();q.wait_for_timeout(300);assert drawer.is_visible();assert drawer.evaluate('(e)=>getComputedStyle(e).opacity')=='1';q.mouse.click(380,200);q.wait_for_function('!document.getElementById("profileMenu").open');assert not q.evaluate('document.body.classList.contains("sidebar-mobile-open")')
 q.locator('#navigationToggle').click();q.wait_for_timeout(300);q.locator('#sidebarUserToggle').focus();q.keyboard.press('Tab');assert q.evaluate('document.activeElement.hasAttribute("data-profile-close")');q.keyboard.press('Shift+Tab');assert q.evaluate('document.activeElement.id')=='sidebarUserToggle';q.keyboard.press('Enter');assert q.locator('#sidebarUserMenu').is_visible();q.keyboard.press('Escape');assert drawer.evaluate('(e)=>e.open');assert q.locator('#sidebarUserMenu').is_hidden();q.keyboard.press('Escape');q.wait_for_function('!document.getElementById("profileMenu").open');assert q.evaluate('JSON.stringify(state)')==before
 q.emulate_media(reduced_motion='reduce');q.locator('#navigationToggle').click();assert drawer.evaluate('(e)=>getComputedStyle(e).animationName')=='none';q.keyboard.press('Escape');assert not drawer.evaluate('(e)=>e.open')
 # Resizing mobile → desktop restores the saved desktop width, not the mobile expanded state.
 q.set_viewport_size({'width':1200,'height':900});assert drawer.get_attribute('data-compact')=='true';assert drawer.bounding_box()['width']==76;q.locator('[data-profile-compact]').click();assert drawer.bounding_box()['width']==264;q.set_viewport_size({'width':390,'height':844});q.locator('#navigationToggle').click();q.keyboard.press('Escape');q.set_viewport_size({'width':1200,'height':900});assert drawer.bounding_box()['width']==264
 q.emulate_media(reduced_motion='no-preference');assert drawer.evaluate('(e)=>getComputedStyle(e).transitionDuration.split(",")[0].trim()')=='0.25s';q.locator('[data-profile-compact]').click();q.wait_for_timeout(300);assert drawer.bounding_box()['width']==76
 assert not errors,errors;(ROOT/'artifacts/sidebar-touch-validation.json').write_text(json.dumps({'status':'passed','checks':['normal entry/width animations','real swipe left over link without navigation','outside backdrop closes and allows reopening','Tab loop, nested menu Escape and restored focus','reduced motion closes immediately','mobile/desktop resize retains saved desktop preference','no learner-state mutations'],'js_errors':errors},indent=2));b.close();print('Passed: real sidebar swipe, background tap, focus and normal/reduced animations')
